package org.codex.nfsugpreview;
import java.io.*;import java.util.*;
public final class ObjScanlineTest {public static void main(String[] args)throws Exception{int count,accepted=0,rejected=0,checks=0;try(DataInputStream in=new DataInputStream(new FileInputStream(args[0]))){if(in.readInt()!=0x31534a4f)throw new AssertionError("Header");int banks=in.readInt();count=in.readInt();byte[][] vram=new byte[banks][98304],palette=new byte[banks][1024];for(int i=0;i<banks;i++){in.readFully(vram[i]);in.readFully(palette[i]);}for(int ci=0;ci<count;ci++){int bank=in.readInt(),display=in.readInt(),row=in.readInt(),blend=in.readInt(),brightness=in.readInt();byte[] oam=new byte[1024];in.readFully(oam);byte[] before=oam.clone(),vb=vram[bank].clone(),pb=palette[bank].clone();boolean expected=in.readInt()!=0;int[] colors=new int[expected?240:0],tags=new int[colors.length];for(int i=0;i<colors.length;i++)colors[i]=in.readInt();for(int i=0;i<tags.length;i++)tags[i]=in.readInt();NativeObjScanline.Row result=null;boolean good=true;try{result=NativeObjScanline.prepared(vram[bank],palette[bank],oam,display,row,blend,brightness);}catch(IllegalArgumentException invalid){good=false;}if(good!=expected)throw new AssertionError("Acceptance "+ci);if(!Arrays.equals(before,oam)||!Arrays.equals(vb,vram[bank])||!Arrays.equals(pb,palette[bank]))throw new AssertionError("Input mutation");if(good){accepted++;if(!Arrays.equals(colors,result.colors())||!Arrays.equals(tags,result.tags()))throw new AssertionError("Candidate/color/tag case "+ci);int[] copy=result.tags();copy[0]^=1;if(!Arrays.equals(tags,result.tags()))throw new AssertionError("Borrowed tags");checks+=480;}else rejected++;}if(in.read()!=-1)throw new AssertionError("Trailing data");}System.out.println("PASS_OBJ_SCANLINE cases="+count+" accepted="+accepted+" rejected="+rejected+" exact_color_and_tag_checks="+checks+" inputs_immutable=true output_owned=true");}}
